import { learningTopics } from "./learning-topics.js";
import { formatJavaSourceForEditor, normalizeJavaSource } from "./java-editor.js";
import { filterAndSortChallenges, studentCatalogNumber } from "./challenge-catalog.mjs";

const $=s=>document.querySelector(s),esc=v=>String(v??"").replace(/[&<>'"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[c]));
class ApiError extends Error{constructor(m,s){super(m);this.status=s}}
const store={token:()=>sessionStorage.getItem("scai-token"),save:u=>{sessionStorage.setItem("scai-token",u.token);sessionStorage.setItem("scai-user",JSON.stringify(u))},clear:()=>{sessionStorage.removeItem("scai-token");sessionStorage.removeItem("scai-user")}};
const api={async r(u,o={}){let token=store.token(),r=await fetch(u,{credentials:"omit",headers:{"Content-Type":"application/json",...(token?{Authorization:`Bearer ${token}`}:{})},...o}),t=await r.text(),b;try{b=t?JSON.parse(t):null}catch{}if(!r.ok)throw new ApiError(b?.detail||b?.message||`Request failed (${r.status})`,r.status);return b},login:(email,password)=>api.r("/api/auth/login",{method:"POST",body:JSON.stringify({email,password})}),register:(name,email,password)=>api.r("/api/auth/register",{method:"POST",body:JSON.stringify({name,email,password})}),me:()=>api.r("/api/auth/me"),challenges:()=>api.r("/challenges"),challenge:id=>api.r(`/challenges/${id}`),prerequisites:id=>api.r(`/challenges/${id}/prerequisites`),submit:(id,sourceCode)=>api.r(`/challenges/${id}/submissions`,{method:"POST",body:JSON.stringify({sourceCode})}),summary:()=>api.r("/api/student/summary"),history:()=>api.r("/api/student/history"),analytics:()=>api.r("/api/student/analytics"),analysis:id=>api.r(`/submissions/${id}/analysis`),profile:name=>api.r("/api/student/profile",{method:"PUT",body:JSON.stringify({name})}),password:(currentPassword,newPassword)=>api.r("/api/student/password",{method:"PUT",body:JSON.stringify({currentPassword,newPassword})})};
const state={user:null,challenges:[],summary:null,history:[],active:null},admin=()=>state.user?.role==="ADMIN",pill=x=>`<span class="pill ${/PASS|SAFE|SOLVED/.test(x)?"pass":/FAIL|VULNERABLE/.test(x)?"fail":"gray"}">${esc(x||"—")}</span>`,catalogNumber=c=>c.catalogNumber??c.challengeNumber;
function out(){store.clear();state.user=null;auth()}function bad(e){if(e.status===401){out();return true}}
function shell(h,p){let q=[["home","Home"],["challenges","Challenges"],["learning","Learning Hub"],["analytics","Analytics"],["history","Submission History"],["profile","Profile"]],name=esc(state.summary?.name||state.user?.name||state.user?.email),account=p==="home"?`<span class="topbar-actions"><button type="button" class="home-user-chip">${name}</button><button type="button" class="secondary logout-button" id="logout">Logout</button></span>`:`<span class="user-chip">${name}</span>`;$("#app").innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand">SecureCode <span>AI</span></div><nav class="nav">${q.map(x=>`<button data-go="${x[0]}" class="${p===x[0]?"active":""}">${x[1]}</button>`).join("")}</nav></aside><main class="main"><header class="topbar"><strong>${q.find(x=>x[0]===p)?.[1]}</strong>${account}</header><div class="page">${h}</div></main></div>`;document.querySelectorAll("[data-go]").forEach(x=>x.onclick=()=>go(x.dataset.go));$("#logout")?.addEventListener("click",out)}function go(p){history.pushState({},"",`#/${p}`);route()}
function auth(m="login"){let l=m==="login";$("#app").innerHTML=`<main class="auth-layout"><section class="auth-card"><div class="brand">SecureCode <span>AI</span></div><h1>${l?"Welcome back":"Create account"}</h1><form id="f">${l?"":'<label class="field">Name<input name="name" required></label>'}<label class="field">Email<input name="email" type="email" required></label><label class="field">Password<input name="password" type="password" minlength="${l?1:12}" required></label><div id="n"></div><button class="primary">${l?"Sign in":"Register"}</button></form><button class="link-button" id="s">${l?"Register":"Sign in"}</button></section></main>`;$("#s").onclick=()=>auth(l?"register":"login");$("#f").onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target);try{let u=l?await api.login(f.get("email"),f.get("password")):await api.register(f.get("name"),f.get("email"),f.get("password"));if(!l){$("#n").textContent="Registered. Please sign in.";return}store.save(u);state.user=u;if(u.role==="ADMIN"){location.replace("/admin.html");return}history.replaceState({},"","#/home");route()}catch(x){$("#n").textContent=x.message}}}
async function home(){shell("Loading…","home");try{state.summary=await api.summary();let s=state.summary;shell(`<h1 class="page-title">Welcome, ${esc(s.name)}</h1><p class="page-intro">SecureCode AI helps you build secure coding habits by practicing realistic programming challenges and understanding the security evidence behind each submission.</p><section class="card home-guide"><h2>How to learn here</h2><p>Learn secure coding concepts, practice challenges, submit your code, and use the functional and security evaluations to improve your next attempt.</p><p class="learning-flow">Learn <span>→</span> Practice <span>→</span> Submit <span>→</span> Functional Evaluation <span>→</span> Security Evaluation <span>→</span> Analyze <span>→</span> Improve</p></section><div class="grid three">${[[s.challengesSolved,"Challenges solved"],[s.challengesAttempted,"Challenges attempted"],[s.totalSubmissions,"Total submissions"]].map(x=>`<div class="card"><div class="stat">${x[0]}</div><div class="stat-label">${x[1]}</div></div>`).join("")}</div><button class="primary" id="b">Browse challenges</button>`,"home");$("#b").onclick=()=>go("challenges")}catch(e){if(!bad(e))shell(esc(e.message),"home")}}
function learningHub(){let cards=learningTopics.map(topic=>`<article class="card learning-card"><h2>${esc(topic.title)}</h2><dl><dt>What it is</dt><dd>${esc(topic.definition)}</dd><dt>Where it occurs</dt><dd>${esc(topic.where)}</dd><dt>Simple example</dt><dd><code>${esc(topic.example)}</code></dd><dt>Impact</dt><dd>${esc(topic.impact)}</dd><dt>Secure coding principle</dt><dd>${esc(topic.principle)}</dd></dl></article>`).join("");shell(`<h1 class="page-title">Learning Hub</h1><p class="page-intro">Learn the fundamentals behind every injection challenge before you start coding.</p><div class="grid two">${cards}</div>`,"learning")}
function card(c){let solved=c.solved?'<span class="solved-badge">Solved</span>':"",locked=c.locked?'<p class="locked-note">Locked — complete prerequisites first.</p>':"";return `<article class="card challenge-card ${c.locked?"locked-card":""}">${solved}<div class="challenge-meta">${pill(`Challenge ${catalogNumber(c)}`)} <span class="difficulty-pill difficulty-${String(c.difficulty||"").toLowerCase()}">${esc(c.difficulty||"—")}</span> ${pill(c.language)}</div><h2>${esc(c.title)}</h2><p>${esc(c.description||"Complete the required prerequisites to view this challenge.")}</p>${locked}<p class="muted">Attempts: ${c.attemptsUsed}/5 · Remaining: ${c.attemptsRemaining}</p><button class="primary" data-open="${c.id}">${c.locked?"View prerequisites":"Open challenge"}</button></article>`}
function challengeOption(values,label){return `<select id="${label}"><option value="">All ${label.replace("challenge-","")}</option>${values.map(value=>`<option value="${esc(value)}">${esc(value)}</option>`).join("")}</select>`}function renderChallenges(){let query=$("#challenge-search").value.trim().toLowerCase(),type=$("#challenge-type").value,language=$("#challenge-language").value,difficulty=$("#challenge-difficulty").value,status=$("#challenge-status").value,sort=$("#challenge-sort").value,rank={EASY:1,MEDIUM:2,HARD:3};let shown=state.challenges.filter(c=>[c.challengeNumber,c.title,c.description,c.vulnerabilityType,c.vulnerabilitySubtype].some(value=>String(value||"").toLowerCase().includes(query))&&(!type||c.vulnerabilityType===type)&&(!language||c.language===language)&&(!difficulty||c.difficulty===difficulty)&&(!status||(status==="solved"?c.solved:!c.solved)));shown.sort((a,b)=>sort==="difficulty"?(rank[a.difficulty]||0)-(rank[b.difficulty]||0)||a.title.localeCompare(b.title):sort==="attempts"?a.attemptsRemaining-b.attemptsRemaining||a.title.localeCompare(b.title):a.title.localeCompare(b.title));$("#list").innerHTML=shown.length?shown.map(card).join(""):'<div class="card empty">No challenges match these filters.</div>';document.querySelectorAll("[data-open]").forEach(x=>x.onclick=()=>go(`challenge/${x.dataset.open}`))}async function challenges(){shell(`<h1 class="page-title">Challenges</h1><div id="challenge-filters" class="filters"><input id="challenge-search" type="search" placeholder="Search challenges...">${challengeOption([...new Set(state.challenges.map(c=>c.vulnerabilityType).filter(Boolean))],"challenge-type")}${challengeOption([...new Set(state.challenges.map(c=>c.language).filter(Boolean))],"challenge-language")}${challengeOption([...new Set(state.challenges.map(c=>c.difficulty).filter(Boolean))],"challenge-difficulty")}<select id="challenge-status"><option value="">All progress</option><option value="solved">Solved</option><option value="unsolved">Unsolved</option></select><select id="challenge-sort"><option value="title">Sort: title</option><option value="difficulty">Sort: difficulty</option><option value="attempts">Sort: attempts remaining</option></select></div><div id="list" class="grid two"></div>`,"challenges");try{state.challenges=await api.challenges();let filters=$("#challenge-filters");filters.innerHTML=`<input id="challenge-search" type="search" placeholder="Search challenges...">${challengeOption([...new Set(state.challenges.map(c=>c.vulnerabilityType).filter(Boolean))],"challenge-type")}${challengeOption([...new Set(state.challenges.map(c=>c.language).filter(Boolean))],"challenge-language")}${challengeOption([...new Set(state.challenges.map(c=>c.difficulty).filter(Boolean))],"challenge-difficulty")}<select id="challenge-status"><option value="">All progress</option><option value="solved">Solved</option><option value="unsolved">Unsolved</option></select><select id="challenge-sort"><option value="title">Sort: title</option><option value="difficulty">Sort: difficulty</option><option value="attempts">Sort: attempts remaining</option></select>`;filters.querySelectorAll("input,select").forEach(x=>{x.oninput=renderChallenges;x.onchange=renderChallenges});renderChallenges()}catch(e){if(!bad(e))$("#list").textContent=e.message}}
renderChallenges=()=>{let sort=$("#challenge-sort"),query=$("#challenge-search").value,difficulty=$("#challenge-difficulty").value,type=$("#challenge-type").value,language=$("#challenge-language").value,status=$("#challenge-status").value;if(!sort.querySelector("option[value='number-asc']"))sort.insertAdjacentHTML("beforeend",'<option value="number-asc">Challenge Number: Ascending</option><option value="number-desc">Challenge Number: Descending</option>');let shown=filterAndSortChallenges(state.challenges.filter(c=>(!type||c.vulnerabilityType===type)&&(!language||c.language===language)&&(!status||(status==="solved"?c.solved:!c.solved))),{query,difficulty,sort:sort.value});$("#list").innerHTML=shown.length?shown.map(card).join(""):'<div class="card empty">No challenges match these filters.</div>';document.querySelectorAll("[data-open]").forEach(x=>x.onclick=()=>go(`challenge/${x.dataset.open}`))};
const renderChallengeList = renderChallenges;
renderChallenges=()=>{let sort=$("#challenge-sort");if(!sort.dataset.initialized){sort.querySelector("option[value='title']")?.remove();sort.value="difficulty";sort.dataset.initialized="true"}return renderChallengeList()};
function real(c){let v=c.vulnerabilitySubtype||c.vulnerabilityType||"unsafe code pattern";return `A ${c.language} application can introduce ${v}${c.cwe?` (${c.cwe})`:""} when processing user-controlled data in a request handler, background job, or integration endpoint. Validate the data and use a safe API before it reaches the sensitive operation.`}
function prerequisiteGrid(p){return `<section class="card prerequisite-panel"><h2>Prerequisites</h2>${p.accessible?"":'<p class="locked-note">Complete every prerequisite to unlock submission.</p>'}<div class="prerequisite-grid">${p.prerequisites.map((x,i)=>`<button type="button" class="prerequisite-item ${x.completed?"complete":"incomplete"}" data-prereq="${x.id}" aria-label="Challenge ${x.catalogNumber??x.challengeNumber}: ${x.title}, ${x.completed?"completed":"incomplete"}" title="${esc(x.title)} — ${x.completed?"completed":"incomplete"}"><span class="prerequisite-number">${i+1}</span><span class="difficulty-pill difficulty-${x.difficulty.toLowerCase()}">${esc(x.difficulty)}</span><strong>${x.completed?"✓":esc(x.catalogNumber??x.challengeNumber)}</strong></button>`).join("")}</div></section>`}
async function submit(){let b=$("#sub"),challengeId=state.active.id;b.disabled=true;try{let r=await api.submit(challengeId,normalizeJavaSource($("#code").value));if(r.status==="STARTER_CODE"){$("#note").innerHTML=`<p class="notice">Submitted code is starter code</p>`;return}$("#note").innerHTML=`<p class="notice success">Attempt ${r.attemptNumber} saved · Learning Score ${r.learningScore}/100</p>`;modal(r.submissionId,()=>{state.active=null;editor(challengeId)})}catch(e){$("#note").textContent=e.message;b.disabled=false;bad(e)}}
async function editor(id){shell("Loading…","challenges");try{let c=state.active=await api.challenge(id),blocked=c.locked,off=blocked||!c.attemptsRemaining,tests=c.testCases.length?c.testCases.map(t=>`<div class="test-case-view"><strong>${t.hidden?"Hidden":"Visible"} test ${t.position+1}</strong><p>Input: ${esc(t.inputData)}</p><p>Expected output: ${esc(t.expectedOutput)}</p></div>`).join(""):"<p>No test cases available.</p>",lockNote=blocked?'<p class="notice">Submission is locked until all prerequisites are completed.</p>':"";shell(`<button class="link-button" id="back">← Back to Challenges</button><h1 class="page-title">Challenge ${esc(catalogNumber(c))}: ${esc(c.title)}</h1>${c.prerequisites?.length?prerequisiteGrid({prerequisites:c.prerequisites,accessible:!blocked}):""}<div class="editor-layout"><section class="details"><article class="card"><h2>Challenge details</h2><p><b>Description:</b> ${esc(c.description)}</p><p><b>Vulnerability type:</b> ${esc(c.vulnerabilityType||"—")}</p><p><b>Vulnerability subtype:</b> ${esc(c.vulnerabilitySubtype||"—")}</p><p><b>Difficulty:</b> ${esc(c.difficulty)}</p><p><b>Supported language:</b> ${esc(c.language)}</p></article><article class="card"><h2>Test cases</h2>${tests}</article><article class="card"><h2>Real World Use</h2><p>${esc(real(c))}</p></article></section><section class="card editor-card"><textarea id="code" class="editor"></textarea><div id="note">${lockNote}</div><div class="editor-actions"><button class="primary" id="sub" ${off?"disabled":""}>${blocked?"Complete prerequisites to submit":off?"All 5 attempts used":"Submit Code"}</button></div></section></div>`,"challenges");$("#code").value=formatJavaSourceForEditor(c.starterCode);$("#back").onclick=()=>go("challenges");document.querySelectorAll("[data-prereq]").forEach(x=>x.onclick=()=>go(`challenge/${x.dataset.prereq}`));if(!off)$("#sub").onclick=submit}catch(e){if(!bad(e))shell(esc(e.message),"challenges")}}
function findingsBlock(groups){if(!groups?.length)return "";return `<section class="card"><h2>Finding</h2>${groups.map(group=>`<h3>${esc(group.displayName)}</h3>${group.findings.map(finding=>`<p>${esc(finding.finding)}${finding.cwe?`<br><span class="muted">${esc(finding.cwe)}</span>`:""}</p>`).join("")}`).join("")}</section>`}
function submissionContext(context){return `<aside class="analysis-context"><section class="card"><p class="section-label">Challenge</p><h2>Challenge No. ${esc(context.challengeNumber)}: ${esc(context.challengeTitle)}</h2><p class="analysis-description">${esc(context.challengeDescription)}</p><p class="muted">Language: ${esc(context.language)}</p></section><section class="card"><p class="section-label">Submitted code</p><textarea class="analysis-code" readonly aria-label="Submitted code">${esc(context.submittedCode)}</textarea></section></aside>`}
function analysisBoard(a){let e=a.evidenceSummary;return `<section class="analysis-board"><section class="card analysis-decision"><h2>Overall Decision</h2>${pill(a.overallDecision)}</section><section class="evaluator-grid">${a.evaluators.map(x=>`<article class="card evaluator-card"><h2>${esc(x.displayName)}</h2>${pill(x.available?x.result:"NOT AVAILABLE")}${x.error?`<p class="muted">${esc(x.error)}</p>`:""}</article>`).join("")}</section>${findingsBlock(a.findings)}<section class="card"><h2>Security Evidence</h2><p>Safe Evidence: ${e.safeEvidencePercent}%</p><p>Vulnerability Evidence: ${e.vulnerabilityEvidencePercent}%</p><div class="evidence-bar" aria-label="Safe and vulnerability evidence"><span class="safe" style="width:${e.safeEvidencePercent}%"></span><span class="vulnerable" style="width:${e.vulnerabilityEvidencePercent}%"></span></div><p class="muted">${e.safeCount} SAFE • ${e.vulnerableCount} VULNERABLE</p></section><section class="card"><h2>Assessment</h2>${pill(a.assessment?.evidenceState)}</section><section class="card"><h2>Feedback / Tips</h2><p class="muted">Detailed feedback will appear here when the Feedback Engine is implemented.</p></section></section>`}
async function modal(id,onClose){try{let a=await api.analysis(id),d=document.createElement("div");d.className="modal-backdrop";d.innerHTML=`<div class="modal analysis-modal"><button class="link-button" id="close">Close ×</button><h1>Submission Analysis</h1><div class="analysis-layout">${submissionContext(a.submissionContext)}${analysisBoard(a)}</div></div>`;document.body.append(d);$("#close").onclick=()=>{d.remove();onClose?.()}}catch(e){bad(e)}}
function learningGraph(points){if(!points.length)return '<p class="muted">No submission progress yet.</p>';let width=680,height=230,pad=34,step=(width-pad*2)/Math.max(1,points.length-1),coords=points.map((x,index)=>`${pad+index*step},${height-pad-x.learningScore*(height-pad*2)/100}`).join(" ");return `<svg class="progress-graph analytics-chart" viewBox="0 0 ${width} ${height}" role="img" aria-label="Learning score by chronological submission"><line x1="${pad}" y1="${height-pad}" x2="${width-pad}" y2="${height-pad}" class="chart-axis"/><line x1="${pad}" y1="${pad}" x2="${pad}" y2="${height-pad}" class="chart-axis"/><text x="4" y="${pad+4}">100</text><text x="12" y="${height-pad+4}">0</text><polyline points="${coords}" class="learning-line"/>${points.map((x,index)=>`<circle cx="${pad+index*step}" cy="${height-pad-x.learningScore*(height-pad*2)/100}" r="4" class="learning-point"><title>${esc(`${x.challengeTitle}, attempt ${x.attemptNumber}: ${x.learningScore}`)}</title></circle>`).join("")}</svg><p class="muted">Chronological submission / attempt progression</p>`}function subtypeGraph(items){if(!items.length)return '<p class="muted">No solved challenges yet.</p>';let width=680,height=250,pad=36,max=Math.max(...items.map(x=>x.questionsSolved),1),bar=Math.max(24,(width-pad*2)/items.length-24);return `<svg class="progress-graph analytics-chart" viewBox="0 0 ${width} ${height}" role="img" aria-label="Solved questions by vulnerability subtype"><line x1="${pad}" y1="${height-pad}" x2="${width-pad}" y2="${height-pad}" class="chart-axis"/><line x1="${pad}" y1="${pad}" x2="${pad}" y2="${height-pad}" class="chart-axis"/>${items.map((x,index)=>{let barHeight=x.questionsSolved*(height-pad*2)/max,left=pad+index*((width-pad*2)/items.length)+12,top=height-pad-barHeight;return `<rect x="${left}" y="${top}" width="${bar}" height="${barHeight}" class="subtype-bar"><title>${esc(`${x.vulnerabilitySubtype}: ${x.questionsSolved} questions solved`)}</title></rect><text x="${left+bar/2}" y="${top-6}" text-anchor="middle">${x.questionsSolved}</text><text x="${left+bar/2}" y="${height-pad+16}" text-anchor="middle">${esc(String(x.vulnerabilitySubtype).slice(0,12))}</text>`}).join("")}</svg>`}async function analytics(){shell("Loading…","analytics");try{let[a,s]=await Promise.all([api.analytics(),api.summary()]);state.summary=s;shell(`<h1 class="page-title">Analytics</h1><div class="grid three">${[[a.totalQuestionsSolved,"Total Questions Solved"],[a.totalPassedSubmissions,"Total Passed Submissions"],[`${a.highestSafeEvidencePercent}%`,`Highest Safe Evidence %`],[s.totalSubmissions,"Total Submissions"],[s.averageLearningScore,"Average Learning Score"]].map(x=>`<div class="card"><div class="stat">${x[0]}</div><div class="stat-label">${x[1]}</div></div>`).join("")}</div><section class="card analytics-section"><h2>Overall Learning Progress</h2>${learningGraph(a.learningProgress)}</section><section class="card analytics-section"><h2>Questions Solved by Vulnerability Subtype</h2>${subtypeGraph(a.solvedByVulnerabilitySubtype)}</section>`,"analytics")}catch(e){if(!bad(e))shell(esc(e.message),"analytics")}}
function submittedAt(value){let date=new Date(value);return Number.isNaN(date.valueOf())?"—":new Intl.DateTimeFormat(undefined,{day:"2-digit",month:"short",year:"numeric",hour:"2-digit",minute:"2-digit",hour12:false}).format(date)}async function historyPage(){shell("Loading…","history");try{state.history=await api.history();shell(`<h1 class="page-title">Submission History</h1><div class="card table-wrap"><table class="table"><thead><tr><th>Date</th><th>Challenge</th><th>Attempt</th><th>Safe Evidence %</th><th>Evidence State</th></tr></thead><tbody>${state.history.map(x=>`<tr><td>${esc(submittedAt(x.submittedAt))}</td><td><button class="link-button" data-submission="${x.submissionId}">${esc(x.challengeTitle)}</button></td><td>${x.attemptNumber}/5</td><td>${x.safeEvidencePercent}%</td><td>${pill(x.evidenceState)}</td></tr>`).join("")||'<tr><td colspan="5" class="muted">No submissions yet.</td></tr>'}</tbody></table></div>`,"history");document.querySelectorAll("[data-submission]").forEach(x=>x.onclick=()=>modal(x.dataset.submission))}catch(e){if(!bad(e))shell(esc(e.message),"history")}}
async function profile(){shell("Loading…","profile");try{state.summary=await api.summary();let s=state.summary;shell(`<h1 class="page-title">Profile & settings</h1><div class="grid two"><section class="card"><p>Name: ${esc(s.name)}</p><p>Email: ${esc(s.email)}</p><p>Challenges solved: ${s.challengesSolved}</p></section><section class="card"><form id="name"><label class="field">Name<input name="name" value="${esc(s.name)}" required></label><button class="secondary">Save name</button></form><form id="pass"><label class="field">Current password<input name="current" type="password" required></label><label class="field">New password<input name="next" type="password" minlength="12" required></label><button class="secondary">Change password</button></form><div id="msg"></div><button id="out" class="link-button">Sign out</button></section></div>`,"profile");$("#name").onsubmit=async e=>{e.preventDefault();try{state.summary=await api.profile(new FormData(e.target).get("name"));$("#msg").textContent="Name updated."}catch(x){$("#msg").textContent=x.message}};$("#pass").onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target);try{await api.password(f.get("current"),f.get("next"));$("#msg").textContent="Password updated."}catch(x){$("#msg").textContent=x.message}};$("#out").onclick=out}catch(e){if(!bad(e))shell(esc(e.message),"profile")}}
function route(){if(!state.user)return auth();if(admin()){location.replace("/admin.html");return}let[p,id]=(location.hash.slice(2)||"home").split("/");({home,challenges,learning:learningHub,analytics,history:historyPage,profile,challenge:()=>editor(id)}[p]||home)()}async function restore(){if(!store.token())return auth();try{state.user=await api.me();route()}catch{out()}}window.onpopstate=route;window.onhashchange=route;restore();
function trend(title,items){if(!items?.length)return `<section class="card analytics-section"><h2>${title}</h2><p class="muted">No evaluated attempts yet.</p></section>`;let max=Math.max(...items.map(x=>x.evaluatedAttempts),1);return `<section class="card analytics-section"><h2>${title}</h2><div class="trend-list">${items.map(x=>`<div class="trend-row"><span>${esc(x.period)}</span><span class="trend-bar"><i style="width:${x.evaluatedAttempts*100/max}%"></i></span><span>${x.successfulAttempts}/${x.evaluatedAttempts} passed · ${x.challengesSolved} solved · ${x.accuracyPercent}%</span></div>`).join("")}</div></section>`}function accuracy(items){return `<section class="grid four">${items.map(x=>`<article class="card"><div class="stat">${x.accuracyPercent}%</div><div class="stat-label">${esc(x.difficulty)} accuracy · ${x.successfulAttempts}/${x.evaluatedAttempts} evaluated</div></article>`).join("")}</section>`}function progress(items){return `<section class="card analytics-section table-wrap"><h2>Challenge progress</h2><table class="table"><thead><tr><th>Challenge</th><th>Difficulty</th><th>Status</th><th>Attempts</th><th>Latest</th><th>Best</th><th>Prerequisites</th></tr></thead><tbody>${items.map(x=>`<tr><td>${x.catalogNumber}. ${esc(x.title)}<br><span class="muted">${esc(x.vulnerabilitySubtype)}</span></td><td><span class="difficulty-pill difficulty-${x.difficulty.toLowerCase()}">${esc(x.difficulty)}</span></td><td>${pill(x.status)}${x.locked?'<span class="muted"> Locked</span>':""}</td><td>${x.attempts}</td><td>${pill(x.latestResult)}</td><td>${x.bestLearningScore}</td><td>${x.completedPrerequisites}/${x.prerequisiteCount}</td></tr>`).join("")}</tbody></table></section>`}async function analyticsDashboard(){shell("Loading…","analytics");try{let[a,s]=await Promise.all([api.analytics(),api.summary()]);state.summary=s;shell(`<h1 class="page-title">Analytics</h1><div class="grid three">${[[a.totalActiveChallenges,"Active challenges"],[a.challengesAttempted,"Challenges attempted"],[a.totalQuestionsSolved,"Challenges solved"],[a.challengesNotSolved,"Not yet solved"],[`${a.completionPercent}%`,`Overall completion`],[s.totalSubmissions,"Total submissions"]].map(x=>`<div class="card"><div class="stat">${x[0]}</div><div class="stat-label">${x[1]}</div></div>`).join("")}</div>${accuracy(a.accuracyByDifficulty)}<section class="card analytics-section"><h2>Overall Learning Progress</h2>${learningGraph(a.learningProgress)}</section>${trend("Weekly learning activity (UTC ISO weeks)",a.weeklyTrends)}${trend("Monthly learning activity (UTC calendar months)",a.monthlyTrends)}<section class="card analytics-section"><h2>Questions Solved by Vulnerability Subtype</h2>${subtypeGraph(a.solvedByVulnerabilitySubtype)}</section>${progress(a.challengeProgress)}`,"analytics")}catch(e){if(!bad(e))shell(esc(e.message),"analytics")}}analytics=analyticsDashboard;
function accountMenu(){let chip=document.querySelector(".user-chip,.home-user-chip");if(!chip||chip.dataset.menu)return;chip.dataset.menu="true";chip.classList.add("account-menu-trigger");chip.setAttribute("type","button");chip.setAttribute("aria-haspopup","menu");chip.setAttribute("aria-expanded","false");let menu=document.createElement("div");menu.className="account-menu hidden";menu.setAttribute("role","menu");menu.innerHTML='<button type="button" role="menuitem" data-account="profile">Profile</button><button type="button" role="menuitem" data-account="logout">Logout</button>';chip.parentElement.append(menu);let close=()=>{menu.classList.add("hidden");chip.setAttribute("aria-expanded","false")};chip.onclick=e=>{e.stopPropagation();menu.classList.toggle("hidden");chip.setAttribute("aria-expanded",String(!menu.classList.contains("hidden")))};menu.onclick=e=>{let action=e.target.dataset.account;if(action==="profile")go("profile");if(action==="logout")out();close()};document.addEventListener("click",close,{once:true})}function analysisPage(id){shell("Loading…","analysis");api.analysis(id).then(a=>{shell(`<h1 class="page-title analysis-page-title">Submission Analysis</h1><div class="analysis-page-layout">${submissionContext(a.submissionContext)}${analysisBoard(a)}</div>`,"analysis")}).catch(e=>{if(!bad(e))shell(esc(e.message),"analysis")})}const originalRoute=route;route=function(){if(!state.user)return auth();if(admin()){location.replace("/admin.html");return}let parts=(location.hash.slice(2)||"home").split("/");if(parts[0]==="analysis")return analysisPage(parts[1]);return originalRoute()};modal=(id,onClose)=>go(`analysis/${id}/history`);new MutationObserver(accountMenu).observe(document.getElementById("app"),{childList:true,subtree:true});accountMenu();
api.attempts=id=>api.r(`/api/student/challenges/${id}/attempts`);function attemptPopup(challenge){api.attempts(challenge).then(items=>{let byAttempt=new Map(items.slice().sort((left,right)=>left.attemptNumber-right.attemptNumber).map(item=>[item.attemptNumber,item])),slots=Array.from({length:5},(_,index)=>{let attemptNumber=index+1,item=byAttempt.get(attemptNumber);if(!item)return `<div class="attempt-marker unused"><b>${attemptNumber}</b><span>Unused</span></div>`;let functional=String(item.functionalStatus||"NOT AVAILABLE"),evidence=String(item.evidenceState||""),safe=Number(item.safeEvidencePercent),state=functional==="PASS"&&safe===100?"safe":functional==="FAIL"||(Number.isFinite(safe)&&safe<100&&!evidence.includes("NO SECURITY EVIDENCE"))?"unsafe":"neutral",safety=Number.isFinite(safe)?`${safe}% safe`:"Security result unavailable";return `<button class="attempt-marker ${state}" data-analysis="${item.submissionId}"><b>${attemptNumber}</b><span>${esc(functional)}</span><span>${esc(safety)}</span><span>Score ${esc(item.learningScore)}</span><small>${esc(submittedAt(item.submittedAt))}</small></button>`}).join("");let popup=document.createElement("div");popup.className="modal-backdrop";popup.innerHTML=`<section class="modal attempt-popup" role="dialog" aria-modal="true" aria-labelledby="attempt-title"><header class="attempt-popup-head"><h2 id="attempt-title">Five-attempt history</h2><button class="link-button" id="close-attempts" aria-label="Close attempt history">Close ×</button></header><div class="attempt-popup-body"><p class="muted">Recorded attempts show functional result, safety percentage, learning score, and timestamp. Unused positions are not submissions.</p><div class="attempt-timeline">${slots}</div><p class="muted">${items.length?`${Math.max(0,5-items.length)} slots unused in this view.`:"No attempts yet."}</p></div></section>`;document.body.append(popup);$("#close-attempts").onclick=()=>popup.remove();popup.querySelectorAll("[data-analysis]").forEach(x=>x.onclick=()=>{popup.remove();go(`analysis/${x.dataset.analysis}/analytics`)})}).catch(e=>alert(e.message))}progress=items=>`<section class="card analytics-section table-wrap"><h2>Challenge progress</h2><table class="table"><thead><tr><th>Challenge</th><th>Difficulty</th><th>Status</th><th>Attempts</th><th>Latest</th><th>Best</th><th>Prerequisites</th></tr></thead><tbody>${items.map(x=>`<tr><td><button class="link-button" data-attempts="${x.challengeId}">${x.catalogNumber}. ${esc(x.title)}</button><br><span class="muted">${esc(x.vulnerabilitySubtype)}</span></td><td><span class="difficulty-pill difficulty-${x.difficulty.toLowerCase()}">${esc(x.difficulty)}</span></td><td>${pill(x.status)}${x.locked?'<span class="muted"> Locked</span>':""}</td><td>${x.attempts}</td><td>${pill(x.latestResult)}</td><td>${x.bestLearningScore}</td><td>${x.completedPrerequisites}/${x.prerequisiteCount}</td></tr>`).join("")}</tbody></table></section>`;document.addEventListener("click",event=>{let target=event.target.closest("[data-attempts]");if(target){event.preventDefault();attemptPopup(target.dataset.attempts)}});
function correctPageHeadings(){document.querySelector(".topbar>strong")?.remove();let heading=document.querySelector(".page-title");if(!heading)return;if(heading.textContent.trim().startsWith("Welcome,"))heading.textContent="Home";if(heading.textContent.trim()==="Profile & settings")heading.textContent="Profile"}new MutationObserver(correctPageHeadings).observe(document.getElementById("app"),{childList:true,subtree:true});correctPageHeadings();

home=async function(){shell("Loading…","home");try{state.summary=await api.summary();let s=state.summary,metrics=[[s.challengesSolved,"Challenges solved"],[s.challengesAttempted,"Challenges attempted"],[s.totalSubmissions,"Total submissions"]];shell(`<section class="home-page"><h1 class="page-title">Home</h1><p class="page-intro home-intro">Practice realistic secure-coding challenges and use each evaluation to improve your next attempt.</p><div class="grid home-summary">${metrics.map(([value,label])=>`<section class="card summary-card"><div class="stat">${value}</div><div class="stat-label">${label}</div></section>`).join("")}</div><section class="card home-guide compact-guide"><h2>Build secure coding habits</h2><p>Learn the concept, solve a challenge, then use the functional and security feedback to strengthen your solution.</p></section><div class="home-action"><button class="primary" id="b">Browse challenges</button></div></section>`,"home");$("#b").onclick=()=>go("challenges")}catch(e){if(!bad(e))shell(esc(e.message),"home")}};

card=c=>{let solved=c.solved?'<span class="solved-badge">Solved</span>':"",locked=c.locked?'<p class="locked-note">Locked — complete prerequisites first.</p>':"",type=c.vulnerabilitySubtype||c.vulnerabilityType;return `<article class="card challenge-card ${c.locked?"locked-card":""}">${solved}<div class="challenge-meta">${pill(`Challenge ${catalogNumber(c)}`)} <span class="difficulty-pill difficulty-${String(c.difficulty||"").toLowerCase()}">${esc(c.difficulty||"—")}</span> ${c.language?pill(c.language):""} ${type?`<span class="pill gray challenge-type">${esc(type)}</span>`:""}</div><h2>${esc(c.title)}</h2><p class="challenge-description">${esc(c.description||"Complete the required prerequisites to view this challenge.")}</p>${locked}<p class="muted challenge-attempts">Attempts: ${c.attemptsUsed}/5 · Remaining: ${c.attemptsRemaining}</p><button class="primary" data-open="${c.id}">${c.locked?"View prerequisites":"Open challenge"}</button></article>`};
shell=function(content,page){let nav=[["home","Home"],["challenges","Challenges"],["learning","Learning Hub"],["analytics","Analytics"],["history","Submission History"],["profile","Profile"]],name=esc(state.summary?.name||state.user?.name||state.user?.email);$("#app").innerHTML=`<div class="app-shell"><header class="app-navbar"><button class="nav-brand" data-go="home" aria-label="SecureCode AI home">SecureCode <span>AI</span></button><button type="button" class="nav-toggle" aria-label="Open navigation" aria-expanded="false">Menu</button><nav class="app-nav" aria-label="Main navigation">${nav.map(item=>`<button data-go="${item[0]}" class="${page===item[0]?"active":""}">${item[1]}</button>`).join("")}</nav><div class="nav-spacer"></div><div class="navbar-account"><button type="button" class="navbar-user" aria-haspopup="menu" aria-expanded="false">${name}</button><div class="navbar-dropdown hidden" role="menu"><button type="button" role="menuitem" data-navbar-action="profile">Profile</button><button type="button" role="menuitem" data-navbar-action="logout">Logout</button></div></div></header><main class="app-main"><div class="page">${content}</div></main></div>`;document.querySelectorAll("[data-go]").forEach(button=>button.onclick=()=>go(button.dataset.go));let toggle=document.querySelector(".nav-toggle"),navElement=document.querySelector(".app-nav");toggle.onclick=()=>{let open=navElement.classList.toggle("open");toggle.setAttribute("aria-expanded",String(open))};let user=document.querySelector(".navbar-user"),menu=document.querySelector(".navbar-dropdown"),close=()=>{menu.classList.add("hidden");user.setAttribute("aria-expanded","false")};user.onclick=event=>{event.stopPropagation();menu.classList.toggle("hidden");user.setAttribute("aria-expanded",String(!menu.classList.contains("hidden")))};menu.onclick=event=>{let action=event.target.dataset.navbarAction;if(action==="profile")go("profile");if(action==="logout")out();close()};document.addEventListener("click",close,{once:true});document.addEventListener("keydown",event=>{if(event.key==="Escape")close()},{once:true})};

// Compact Analytics and Learning Hub presentation. These helpers only reshape existing API values.
function difficultyProgress(items){let order=["BASIC","EASY","MEDIUM","HARD"];return `<section class="card analytics-section difficulty-progress"><div class="analytics-section-heading"><div><h2>Progress by difficulty</h2><p class="muted">Solved challenges out of active challenges</p></div></div><div class="difficulty-progress-list">${order.map(difficulty=>{let challenges=items.filter(item=>item.difficulty===difficulty),solved=challenges.filter(item=>item.status==="SOLVED").length,total=challenges.length,percent=total?Math.round(solved*100/total):0;return `<div class="difficulty-progress-row"><span class="difficulty-pill difficulty-${difficulty.toLowerCase()}">${difficulty}</span><span class="difficulty-track" aria-label="${difficulty}: ${solved} of ${total} challenges solved"><i style="width:${percent}%"></i></span><strong>${solved}/${total}</strong></div>`}).join("")}</div></section>`}
function activityAccuracyChart(weekly,monthly){let weeklyEvaluated=(weekly||[]).filter(item=>item.evaluatedAttempts>0),monthlyEvaluated=(monthly||[]).filter(item=>item.evaluatedAttempts>0);if(!weeklyEvaluated.length&&!monthlyEvaluated.length)return `<section class="card analytics-section"><h2>Evaluation accuracy by activity period</h2><p class="muted">No evaluated attempts yet.</p></section>`;let width=720,height=230,left=42,right=14,top=30,lane=66,gap=30,plotWidth=width-left-right,series=[{label:"Weekly · UTC ISO weeks",items:weeklyEvaluated,color:"#2563eb",top},{label:"Monthly · UTC calendar months",items:monthlyEvaluated,color:"#7c3aed",top:top+lane+gap}],render=({label,items,color,top:laneTop})=>{let baseline=laneTop+lane;if(!items.length)return `<text x="${left}" y="${laneTop+22}" class="chart-caption">${label}: no evaluated attempts</text>`;let step=plotWidth/Math.max(1,items.length-1),point=(item,index)=>`${left+index*step},${baseline-item.accuracyPercent*lane/100}`,points=items.map(point).join(" "),labels=items.map((item,index)=>`<text x="${left+index*step}" y="${baseline+15}" text-anchor="middle" class="chart-period">${esc(item.period)}</text>`).join(""),dots=items.map((item,index)=>{let[x,y]=point(item,index).split(",");return `<circle cx="${x}" cy="${y}" r="3" fill="${color}"><title>${esc(`${label} ${item.period}: ${item.accuracyPercent}% accuracy (${item.successfulAttempts}/${item.evaluatedAttempts} evaluated)`)} </title></circle>`}).join("");return `<text x="${left}" y="${laneTop-8}" class="chart-caption">${label}</text><line x1="${left}" y1="${baseline}" x2="${width-right}" y2="${baseline}" class="chart-axis"/><line x1="${left}" y1="${laneTop}" x2="${left}" y2="${baseline}" class="chart-axis"/><text x="8" y="${laneTop+5}" class="chart-caption">100%</text><text x="18" y="${baseline+4}" class="chart-caption">0%</text><polyline points="${points}" fill="none" stroke="${color}" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>${dots}${labels}`};return `<section class="card analytics-section activity-chart"><div class="analytics-section-heading"><div><h2>Evaluation accuracy by activity period</h2><p class="muted">Pass rate uses passed functional evaluations ÷ evaluated functional attempts. Weekly and monthly periods retain their UTC semantics; periods with no evaluations are not plotted.</p></div><div class="chart-legend"><span><i class="weekly"></i>Weekly</span><span><i class="monthly"></i>Monthly</span></div></div><svg class="analytics-chart activity-accuracy-chart" viewBox="0 0 ${width} ${height}" role="img" aria-label="Weekly and monthly functional evaluation accuracy">${series.map(render).join("")}</svg></section>`}
learningGraph=function(points){if(!points.length)return '<p class="muted">No submission progress yet.</p>';let width=680,height=180,pad=30,step=(width-pad*2)/Math.max(1,points.length-1),y=value=>height-pad-value*(height-pad*2)/100,coords=points.map((item,index)=>`${pad+index*step},${y(item.learningScore)}`).join(" ");return `<svg class="progress-graph analytics-chart learning-score-chart" viewBox="0 0 ${width} ${height}" role="img" aria-label="Learning score by chronological submission"><line x1="${pad}" y1="${height-pad}" x2="${width-pad}" y2="${height-pad}" class="chart-axis"/><line x1="${pad}" y1="${pad}" x2="${pad}" y2="${height-pad}" class="chart-axis"/><text x="3" y="${pad+4}" class="chart-caption">100</text><text x="12" y="${height-pad+4}" class="chart-caption">0</text><polyline points="${coords}" class="learning-line"/>${points.map((item,index)=>`<circle cx="${pad+index*step}" cy="${y(item.learningScore)}" r="3.5" class="learning-point"><title>${esc(`${item.challengeTitle}, attempt ${item.attemptNumber}: ${item.learningScore}`)}</title></circle>`).join("")}</svg><p class="muted chart-note">Learning score across submissions in chronological order.</p>`};
subtypeGraph=function(items){if(!items.length)return '<p class="muted">No solved challenges yet.</p>';let wrapLabel=value=>{let words=String(value).trim().split(/\s+/),lines=[],line="",limit=12;words.forEach(word=>{let pieces=word.match(new RegExp(`.{1,${limit}}`,"g"))||[word];pieces.forEach(piece=>{if(line&&`${line} ${piece}`.length>limit){lines.push(line);line=piece}else line=line?`${line} ${piece}`:piece})});if(line)lines.push(line);return lines},labels=items.map(item=>wrapLabel(item.vulnerabilitySubtype)),longestLine=Math.max(...labels.flat().map(line=>line.length),1),slot=Math.max(76,longestLine*6.2+14),pad={top:22,right:16,bottom:18,left:34},plotHeight=126,labelHeight=Math.max(...labels.map(lines=>lines.length))*12,width=Math.max(720,pad.left+pad.right+slot*items.length),height=pad.top+plotHeight+pad.bottom+labelHeight,max=Math.max(...items.map(item=>item.questionsSolved),1),bar=Math.max(12,Math.min(30,slot*.46)),baseline=pad.top+plotHeight;return `<div class="subtype-chart-scroll"><svg class="progress-graph analytics-chart subtype-chart" style="--subtype-chart-min-width:${width}px" viewBox="0 0 ${width} ${height}" role="img" aria-label="Solved questions by vulnerability subtype"><desc>${esc(items.map(item=>`${item.vulnerabilitySubtype}: ${item.questionsSolved} questions solved`).join(". "))}</desc><line x1="${pad.left}" y1="${baseline}" x2="${width-pad.right}" y2="${baseline}" class="chart-axis"/><line x1="${pad.left}" y1="${pad.top}" x2="${pad.left}" y2="${baseline}" class="chart-axis"/>${items.map((item,index)=>{let barHeight=item.questionsSolved*plotHeight/max,left=pad.left+index*slot+(slot-bar)/2,top=baseline-barHeight,center=left+bar/2,lines=labels[index];return `<rect x="${left}" y="${top}" width="${bar}" height="${barHeight}" rx="2" class="subtype-bar"><title>${esc(`${item.vulnerabilitySubtype}: ${item.questionsSolved} questions solved`)}</title></rect><text x="${center}" y="${top-5}" text-anchor="middle" class="chart-value">${item.questionsSolved}</text><text x="${center}" y="${baseline+16}" text-anchor="middle" class="chart-period subtype-label"><title>${esc(item.vulnerabilitySubtype)}</title>${lines.map((line,lineIndex)=>`<tspan x="${center}" dy="${lineIndex?12:0}">${esc(line)}</tspan>`).join("")}</text>`}).join("")}</svg></div>`};
function accuracyCards(items){return `<section class="analytics-accuracy"><div class="analytics-section-heading"><div><h2>Functional evaluation accuracy</h2><p class="muted">Accuracy is separate from challenge completion.</p></div></div><div class="grid four">${items.map(item=>{let hasEvaluations=item.evaluatedAttempts>0,percent=hasEvaluations?item.accuracyPercent:0;return `<article class="card compact-metric accuracy-card"><span class="difficulty-pill difficulty-${item.difficulty.toLowerCase()}">${esc(item.difficulty)}</span><div class="stat">${hasEvaluations?`${percent}%`:"—"}</div><div class="stat-label">${hasEvaluations?`${item.successfulAttempts}/${item.evaluatedAttempts} evaluated attempts passed`:"No evaluated attempts"}</div><span class="accuracy-meter${hasEvaluations?"":" empty"}" aria-label="${esc(item.difficulty)} functional evaluation accuracy${hasEvaluations?`: ${percent}%`:": no evaluated attempts"}"><i style="width:${percent}%"></i></span></article>`}).join("")}</div></section>`}
function metricIcon(index){let paths=["M7 5h10v14H7zM9 3h6v3H9zM10 10h4M10 14h4","M12 3a9 9 0 1 0 9 9M12 7a5 5 0 1 0 5 5M12 11l5-5","M12 4l2 4h5l-4 3 2 5-5-3-5 3 2-5-4-3h5z","M12 3v9h9A9 9 0 1 1 12 3","M6 3h10l3 3v15H6zM14 3v4h5M9 11h6M9 15h4"];return `<span class="metric-icon metric-icon-${index}" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="${paths[index]}"></path></svg></span>`}
analyticsDashboard=async function(){shell("Loading…","analytics");try{let[a,s]=await Promise.all([api.analytics(),api.summary()]);state.summary=s;let metrics=[[a.totalActiveChallenges,"Active challenges"],[a.challengesAttempted,"Challenges attempted"],[a.totalQuestionsSolved,"Challenges solved"],[`${a.completionPercent}%`,`Challenge completion`],[s.totalSubmissions,"Total submissions"]];shell(`<section class="analytics-page"><h1 class="page-title">Analytics</h1><p class="page-intro">A compact view of your active challenge progress and evaluated attempts.</p><div class="grid analytics-summary">${metrics.map(([value,label],index)=>`<article class="card compact-metric">${metricIcon(index)}<div><div class="stat">${value}</div><div class="stat-label">${label}</div></div></article>`).join("")}</div><div class="analytics-top-grid">${difficultyProgress(a.challengeProgress)}${accuracyCards(a.accuracyByDifficulty)}</div><div class="analytics-chart-grid"><section class="card analytics-section"><h2>Overall Learning Progress</h2><p class="muted chart-subtitle">Learning trend across attempts, based on challenge completion and scores.</p>${learningGraph(a.learningProgress)}</section>${activityAccuracyChart(a.weeklyTrends,a.monthlyTrends)}</div><section class="card analytics-section"><h2>Questions Solved by Vulnerability Subtype</h2><p class="muted chart-subtitle">Number of challenges solved in each vulnerability subtype.</p>${subtypeGraph(a.solvedByVulnerabilitySubtype)}</section>${progress(a.challengeProgress)}</section>`,"analytics")}catch(e){if(!bad(e))shell(esc(e.message),"analytics")}};analytics=analyticsDashboard;
learningHub=function(){let cards=learningTopics.map(topic=>`<article class="card learning-card"><h2>${esc(topic.title)}</h2><dl><dt>What it is</dt><dd>${esc(topic.definition)}</dd><dt>Where it occurs</dt><dd>${esc(topic.where)}</dd><dt>Simple example</dt><dd><code>${esc(topic.example)}</code></dd><dt>Impact</dt><dd>${esc(topic.impact)}</dd><dt>Secure coding principle</dt><dd>${esc(topic.principle)}</dd></dl></article>`).join("");shell(`<section class="learning-page"><h1 class="page-title">Learning Hub</h1><p class="page-intro">Learn the fundamentals behind every injection challenge before you start coding.</p><div class="grid two learning-grid">${cards}</div></section>`,"learning")};

function highlightSubmittedCode(line){return esc(line).replace(/\b(public|private|protected|static|final|class|interface|void|int|long|double|boolean|new|return|if|else|for|while|try|catch|throw|throws|import|package)\b/g,'<span class="code-keyword">$1</span>').replace(/(&quot;[^&]*?&quot;)/g,'<span class="code-string">$1</span>').replace(/(\/\/.*)$/g,'<span class="code-comment">$1</span>')}
submissionContext=function(context){let lines=String(context.submittedCode||"").split(/\r?\n/),number=context.catalogNumber??context.challengeNumber;return `<aside class="analysis-context"><section class="card analysis-challenge-card"><div class="analysis-card-head"><h2>Challenge Details</h2><span class="analysis-number">Challenge No. ${esc(number)}</span></div><h3>${esc(context.challengeTitle)}</h3><p class="analysis-description">${esc(context.challengeDescription)}</p><span class="analysis-language">Language: ${esc(context.language)}</span></section><section class="card submitted-code-card"><div class="analysis-card-head"><h2>Submitted Code</h2><button type="button" class="secondary copy-code" id="copy-submitted-code">Copy Code</button></div><div class="submitted-code-scroll" tabindex="0" aria-label="Submitted source code"><ol class="submitted-code-lines">${lines.map(line=>`<li><code>${highlightSubmittedCode(line)||" "}</code></li>`).join("")}</ol></div></section></aside>`}
function evaluatorDetail(item){if(item.error)return item.error;if(!item.available)return "Not available";if(item.evaluator==="JUDGE0")return "Functional correctness";return item.result==="SAFE"?"No issues detected":item.result==="VULNERABLE"?"Issue detected":"Evaluator result"}
function feedbackPanel(feedback){if(!feedback)return "";return `<section class="card analysis-feedback"><h2>Feedback / Tips</h2>${pill(feedback.state)}<h3>${esc(feedback.title)}</h3><p>${esc(feedback.summary)}</p><p><strong>Next step:</strong> ${esc(feedback.guidance)}</p>${feedback.available?`<p class="muted">Source: ${esc(feedback.source)}</p>`:""}</section>`}
analysisBoard=function(a){let evidence=a.evidenceSummary,decisionNote=`Evaluation engine decision: ${esc(a.overallDecision)}.`,assessment=a.assessment?.evidenceState||"NOT_AVAILABLE";return `<section class="analysis-board"><section class="card analysis-decision"><div><h2>Overall Decision</h2><p>${decisionNote}</p></div>${pill(a.overallDecision)}</section><section class="card analysis-evaluators"><div class="analysis-section-head"><div><h2>Evaluator Results</h2><p class="muted">Results from available evaluators for this submission.</p></div></div><div class="evaluator-grid">${a.evaluators.map(item=>`<article class="evaluator-card"><h3>${esc(item.displayName)}</h3>${pill(item.available?item.result:"NOT AVAILABLE")}<p>${esc(evaluatorDetail(item))}</p></article>`).join("")}</div></section><div class="analysis-evidence-grid"><section class="card security-evidence"><h2>Security Evidence</h2><p class="muted">Normalized evidence from completed security evaluators.</p><div class="evidence-summary"><span>Safe Evidence: <strong>${evidence.safeEvidencePercent}%</strong></span><span>Vulnerability Evidence: <strong>${evidence.vulnerabilityEvidencePercent}%</strong></span></div><div class="evidence-bar" aria-label="Safe evidence ${evidence.safeEvidencePercent} percent and vulnerability evidence ${evidence.vulnerabilityEvidencePercent} percent"><span class="safe" style="width:${evidence.safeEvidencePercent}%"></span><span class="vulnerable" style="width:${evidence.vulnerabilityEvidencePercent}%"></span></div><p class="muted">${evidence.safeCount} safe • ${evidence.vulnerableCount} vulnerable</p></section><section class="card analysis-assessment"><h2>Assessment</h2><p class="muted">Final security assessment based on evaluator results.</p>${pill(assessment)}</section></div>${feedbackPanel(a.findings)}</section>`}
analysisBoard=function(a){let evidence=a.evidenceSummary,decisionNote=`Evaluation engine decision: ${esc(a.overallDecision)}.`,assessment=a.assessment?.evidenceState||"NOT_AVAILABLE";return `<section class="analysis-board"><section class="card analysis-decision"><div><h2>Overall Decision</h2><p>${decisionNote}</p></div>${pill(a.overallDecision)}</section><section class="card analysis-evaluators"><div class="analysis-section-head"><div><h2>Evaluator Results</h2><p class="muted">Results from available evaluators for this submission.</p></div></div><div class="evaluator-grid">${a.evaluators.map(item=>`<article class="evaluator-card"><h3>${esc(item.displayName)}</h3>${pill(item.available?item.result:"NOT AVAILABLE")}<p>${esc(evaluatorDetail(item))}</p></article>`).join("")}</div></section><div class="analysis-evidence-grid"><section class="card security-evidence"><h2>Security Evidence</h2><p class="muted">Normalized evidence from completed security evaluators.</p><div class="evidence-summary"><span>Safe Evidence: <strong>${evidence.safeEvidencePercent}%</strong></span><span>Vulnerability Evidence: <strong>${evidence.vulnerableEvidencePercent}%</strong></span></div><div class="evidence-bar" aria-label="Safe evidence ${evidence.safeEvidencePercent} percent and vulnerability evidence ${evidence.vulnerableEvidencePercent} percent"><span class="safe" style="width:${evidence.safeEvidencePercent}%"></span><span class="vulnerable" style="width:${evidence.vulnerableEvidencePercent}%"></span></div><p class="muted">${evidence.safeCount} safe • ${evidence.vulnerableCount} vulnerable</p></section><section class="card analysis-assessment"><h2>Assessment</h2><p class="muted">Final security assessment based on evaluator results.</p>${pill(assessment)}</section></div>${feedbackPanel(a.learningFeedback)}${a.findings?.length?findingsBlock(a.findings):""}</section>`}
async function copySubmittedCode(source){try{if(navigator.clipboard?.writeText)await navigator.clipboard.writeText(source);else{let area=document.createElement("textarea");area.value=source;document.body.append(area);area.select();document.execCommand("copy");area.remove()}let button=$("#copy-submitted-code");if(button){button.textContent="Copied";setTimeout(()=>button.textContent="Copy Code",1600)}}catch{let button=$("#copy-submitted-code");if(button)button.textContent="Copy unavailable"}}
analysisPage=async function(id){shell("Loading…","analysis");try{let analysis=await api.analysis(id);shell(`<section class="submission-analysis-page"><h1 class="page-title analysis-page-title">Submission Analysis</h1><p class="page-intro">Detailed evaluation of your submission, including functional correctness and security analysis.</p><div class="analysis-page-layout">${submissionContext(analysis.submissionContext)}${analysisBoard(analysis)}</div></section>`,"analysis");$("#copy-submitted-code")?.addEventListener("click",()=>copySubmittedCode(analysis.submissionContext.submittedCode||""))}catch(error){if(!bad(error))shell(esc(error.message),"analysis")}};

function attemptHistoryGraph(items){let byAttempt=new Map(items.map(item=>[item.attemptNumber,item])),width=700,height=190,left=42,right=24,top=18,bottom=42,plotWidth=width-left-right,plotHeight=height-top-bottom,point=(item,index)=>`${left+index*plotWidth/4},${top+(100-Number(item.safeEvidencePercent||0))*plotHeight/100}`,recorded=[1,2,3,4,5].map(number=>byAttempt.get(number)).filter(Boolean),polyline=recorded.map(item=>point(item,item.attemptNumber-1)).join(" ");return `<svg class="attempt-history-chart" viewBox="0 0 ${width} ${height}" role="img" aria-label="Safety percentage for each recorded attempt"><line x1="${left}" y1="${top}" x2="${left}" y2="${height-bottom}" class="chart-axis"/><line x1="${left}" y1="${height-bottom}" x2="${width-right}" y2="${height-bottom}" class="chart-axis"/><text x="8" y="${top+4}" class="chart-caption">100%</text><text x="18" y="${height-bottom+4}" class="chart-caption">0%</text>${recorded.length>1?`<polyline points="${polyline}" class="attempt-safety-line"/>`:""}${[1,2,3,4,5].map((number,index)=>{let item=byAttempt.get(number),x=left+index*plotWidth/4;if(!item)return `<circle cx="${x}" cy="${height-bottom}" r="5" class="attempt-empty-point"/><text x="${x}" y="${height-18}" text-anchor="middle" class="chart-period">Attempt ${number}</text>`;let safe=Number(item.safeEvidencePercent||0),y=top+(100-safe)*plotHeight/100,state=item.functionalStatus==="PASS"&&safe===100?"safe":item.functionalStatus==="FAIL"||safe<100?"unsafe":"neutral";return `<circle cx="${x}" cy="${y}" r="5" class="attempt-point ${state}"><title>${esc(`Attempt ${number}: ${safe}% safe, score ${item.learningScore}, ${item.functionalStatus}`)}</title></circle><text x="${x}" y="${y-10}" text-anchor="middle" class="attempt-chart-value">${safe}%</text><text x="${x}" y="${height-18}" text-anchor="middle" class="chart-period">Attempt ${number}</text>`}).join("")}</svg>`}
attemptPopup=function(challenge){api.attempts(challenge).then(rawItems=>{let items=rawItems.slice().sort((left,right)=>left.attemptNumber-right.attemptNumber),byAttempt=new Map(items.map(item=>[item.attemptNumber,item])),details=[1,2,3,4,5].map(number=>{let item=byAttempt.get(number);if(!item)return `<div class="attempt-graph-detail unused"><strong>Attempt ${number}</strong><span>Unused</span></div>`;return `<button class="attempt-graph-detail" data-analysis="${item.submissionId}"><strong>Attempt ${number}</strong><span>${esc(item.functionalStatus||"NOT AVAILABLE")} · ${esc(item.safeEvidencePercent)}% safe</span><span>Score ${esc(item.learningScore)}</span><small>${esc(submittedAt(item.submittedAt))}</small></button>`}).join(""),popup=document.createElement("div");popup.className="modal-backdrop";popup.innerHTML=`<section class="modal attempt-popup" role="dialog" aria-modal="true" aria-labelledby="attempt-title"><header class="attempt-popup-head"><h2 id="attempt-title">Five-attempt history</h2><button class="link-button" id="close-attempts" aria-label="Close attempt history">Close ×</button></header><div class="attempt-popup-body"><p class="muted">Safety percentage across the five available attempt positions. Select a recorded attempt to view its analysis.</p>${attemptHistoryGraph(items)}<div class="attempt-graph-details">${details}</div><p class="muted">${items.length?`${Math.max(0,5-items.length)} slots unused in this view.`:"No attempts yet."}</p></div></section>`;document.body.append(popup);$("#close-attempts").onclick=()=>popup.remove();popup.querySelectorAll("[data-analysis]").forEach(button=>button.onclick=()=>{popup.remove();go(`analysis/${button.dataset.analysis}/analytics`)})}).catch(error=>alert(error.message))};
